SELECT ROUND(100.0 * SUM(CASE WHEN f.first_answer IS NOT NULL AND julianday(f.first_answer) - julianday(q.creation_date) <= 1 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_answered_within_24h
FROM posts_questions q
LEFT JOIN (SELECT parent_id, MIN(creation_date) AS first_answer FROM posts_answers GROUP BY parent_id) f ON f.parent_id = q.post_id;
